public class ValueDescriberTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("describe(42)", "int: 42", ValueDescriber.describe(42));
        check("describe(-7)", "int: -7", ValueDescriber.describe(-7));
        check("describe(\"hey\")", "string of length 3", ValueDescriber.describe("hey"));
        check("describe(\"\")", "string of length 0", ValueDescriber.describe(""));
        check("describe(new int[]{1,2,3})", "array of 3 ints", ValueDescriber.describe(new int[] { 1, 2, 3 }));
        check("describe(new int[0])", "array of 0 ints", ValueDescriber.describe(new int[0]));
        check("describe(null)", "null", ValueDescriber.describe(null));
        check("describe(3.5) is unknown", "unknown", ValueDescriber.describe(3.5));
        check("describe(new long[]{1}) is unknown", "unknown", ValueDescriber.describe(new long[] { 1L }));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

