public class ValueDescriber {

    public static String describe(Object o) {
        if (o == null) {
            return "null";
        }
        if (o instanceof Integer i) {
            return "int: " + i;
        }
        if (o instanceof String s) {
            return "string of length " + s.length();
        }
        if (o instanceof int[] a) {
            return "array of " + a.length + " ints";
        }
        return "unknown";
    }
}
